func:
// Stand-in for your real data source (MQTT, Modbus, etc.). The only
// part that matters for the Bad-quality-flagging feature is the
// heartbeat line at the end - set it whenever real data genuinely
// arrives, regardless of whether values changed.
const data = flow.get("OpcData", "memoryOnly") || {};

data["Machine1.Speed"] = Math.round((50 + Math.random() * 20) * 10) / 10;
data["Machine1.Running"] = Math.random() > 0.1;
data["Machine1.PartCount"] = (data["Machine1.PartCount"] || 0) + 1;
data["Machine2.Temperature"] = Math.round((60 + Math.random() * 15) * 10) / 10;
data["Machine2.Status"] = Math.floor(Math.random() * 3);

flow.set("OpcData", data, "memoryOnly");

// Heartbeat - disable this inject node (and redeploy) to simulate the
// data source going silent, and watch tags flip to Bad quality after
// staleDataThresholdMs (default 10s).
flow.set("OpcDataLastUpdate", Date.now(), "memoryOnly");

return null;

addressSpaceScript:
function constructAddressSpaceScript(server, addressSpace, eventObjects, done) {
  addressSpaceHelper.buildBlueprintAddressSpace(
    server,
    addressSpace,
    eventObjects,
    done,
    node,
    sandboxFlowContext,
    coreServer.choreCompact.opcua,
    {
      namespaceUri: node.namespaceUri,
      staleDataThresholdMs: 10000,
      staleDataStatusCode: "BadNoCommunication"
    }
  );
}
